using Microsoft.EntityFrameworkCore; using server.Models;
namespace server.Data;
public class GameDbContext(DbContextOptions<GameDbContext> options) : DbContext(options) { public DbSet<MenuItem> MenuItems => Set<MenuItem>(); public DbSet<PhoMenuItem> PhoMenuItems => Set<PhoMenuItem>(); public DbSet<Customer> Customers => Set<Customer>(); public DbSet<Player> Players => Set<Player>(); public DbSet<Order> Orders => Set<Order>(); public DbSet<RandomEvent> RandomEvents => Set<RandomEvent>(); public DbSet<EventOption> EventOptions => Set<EventOption>(); public DbSet<Upgrade> Upgrades => Set<Upgrade>(); public DbSet<Achievement> Achievements => Set<Achievement>(); public DbSet<Topping> Toppings => Set<Topping>(); public DbSet<GameJourney> GameJourneys => Set<GameJourney>(); public DbSet<GameHistory> GameHistories => Set<GameHistory>(); protected override void OnModelCreating(ModelBuilder modelBuilder) { modelBuilder.Entity<GameJourney>().Property(x => x.PlayerId).ValueGeneratedNever(); modelBuilder.Entity<Player>().Property(p => p.Money).HasPrecision(18, 2); modelBuilder.Entity<PhoMenuItem>().Property(p => p.BasePrice).HasPrecision(18, 2); modelBuilder.Entity<PhoMenuItem>().Property(p => p.PhoType).HasConversion<string>(); modelBuilder.Entity<Customer>().Property(c => c.CustomerType).HasConversion<string>(); modelBuilder.Entity<Customer>().Property(c => c.PreferredPhoType).HasConversion<string>(); modelBuilder.Entity<Order>().Property(o => o.PhoType).HasConversion<string>(); modelBuilder.Entity<Order>().Property(o => o.Price).HasPrecision(18, 2); modelBuilder.Entity<RandomEvent>().Property(e => e.EventType).HasConversion<string>(); modelBuilder.Entity<EventOption>().Property(o => o.MoneyChange).HasPrecision(18, 2); modelBuilder.Entity<Upgrade>().Property(u => u.Category).HasConversion<string>(); modelBuilder.Entity<Upgrade>().Property(u => u.Cost).HasPrecision(18, 2); modelBuilder.Entity<Topping>().Property(t => t.Price).HasPrecision(18, 2); modelBuilder.Entity<GameHistory>().Property(h => h.MoneyChange).HasPrecision(18, 2); modelBuilder.Entity<GameHistory>().HasIndex(h => new { h.PlayerId, h.CreatedAt }); modelBuilder.Entity<RandomEvent>().HasMany(e => e.Options).WithOne(o => o.RandomEvent).HasForeignKey(o => o.RandomEventId).OnDelete(DeleteBehavior.Cascade); } }
